@CategoryID_8a1ad2fd UNIQUEIDENTIFIER,
@UserQuestion_8a1ad2fd NVARCHAR(MAX),
@Description_8a1ad2fd NVARCHAR(MAX),
@SQL_8a1ad2fd NVARCHAR(MAX),
