@OriginalSQL_8a1ad2fd NVARCHAR(MAX),
@Feedback_8a1ad2fd NVARCHAR(MAX),
@Status_8a1ad2fd NVARCHAR(15),
@QualityRank_8a1ad2fd INT,
@ExecutionCostRank_8a1ad2fd INT,
@UsesTemplate_8a1ad2fd BIT,
@AuditQueryRuns_8a1ad2fd BIT,
@CacheEnabled_8a1ad2fd BIT,
@CacheTTLMinutes_8a1ad2fd INT,
@CacheMaxSize_8a1ad2fd INT,
@EmbeddingVector_8a1ad2fd NVARCHAR(MAX),
@EmbeddingModelID_8a1ad2fd UNIQUEIDENTIFIER,
@CacheValidationSQL_8a1ad2fd NVARCHAR(MAX),
@SQLDialectID_8a1ad2fd UNIQUEIDENTIFIER,
@Reusable_8a1ad2fd BIT,
@ID_8a1ad2fd UNIQUEIDENTIFIER
SET
  @Name_8a1ad2fd = N'rasa.io - Contact Topics by Newsletter'
SET
  @CategoryID_8a1ad2fd = '0FDEC5C4-B6B9-47CC-A8D5-F316DF611C4D'
SET
  @UserQuestion_8a1ad2fd = N'What topics is each contact interested in, in each newsletter, and what is their email?'
SET
  @Description_8a1ad2fd = N'Each contact''s topic interests per newsletter, from the topic clouds rasa.io builds from the articles they clicked, with the contact''s email and the newsletter''s name.'
SET
  @SQL_8a1ad2fd = N'-- Each contact''s topics in each newsletter, with the contact''s email and the newsletter''s name.
-- contact_id is the rasa.io contact id: the same id in Contact, Newsletter Contact and the topic tables.
SELECT
    t.newsletter_id AS NewsletterID,
    n.name AS Newsletter,
    t.contact_id AS ContactID,
    c.email AS Email,
    t.topic AS Topic,
    t.num_clicks AS Clicks,
    t.weight AS Weight,
    t.first_click AS FirstClick,
    t.last_click AS LastClick,
    t.effective_date AS EffectiveDate
FROM {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Newsletter_Contact_Topic t
INNER JOIN {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Contact c ON c.id = t.contact_id
LEFT JOIN {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Newsletter n ON n.id = t.newsletter_id
'
SET
  @TechnicalDescription_8a1ad2fd = N'Newsletter_Contact_Topic joined to Contact on contact_id = Contact.id for the email, and to Newsletter for its name. One row per newsletter, contact and topic. Weight is the topic''s share of the contact''s clicks in that newsletter. Only contacts who have clicked have rows.'
SET
  @Status_8a1ad2fd = N'Approved'
SET
  @QualityRank_8a1ad2fd = 8
SET
  @ExecutionCostRank_8a1ad2fd = 3
SET
  @UsesTemplate_8a1ad2fd = 1
SET
  @AuditQueryRuns_8a1ad2fd = 0
