SET
  @Name_41a0b455 = N'rasa.io - Contact Topics Across Newsletters'
SET
  @CategoryID_41a0b455 = '0FDEC5C4-B6B9-47CC-A8D5-F316DF611C4D'
SET
  @UserQuestion_41a0b455 = N'What is each person interested in across all our newsletters, by email?'
SET
  @Description_41a0b455 = N'Each person''s topic interests rolled up across every newsletter, one row per contact and topic, with the email. Clicks are summed and the strongest weight is kept.'
SET
  @SQL_41a0b455 = N'-- A person''s interests across every newsletter, one row per contact and topic, with the email.
-- Clicks are summed, the strongest per-newsletter weight is kept and the click window is widened,
-- the same way rasa.io merges a contact''s topics across an account''s newsletters.
SELECT
    t.contact_id AS ContactID,
    c.email AS Email,
    t.topic AS Topic,
    SUM(t.num_clicks) AS Clicks,
    MAX(t.weight) AS Weight,
    COUNT(DISTINCT t.newsletter_id) AS Newsletters,
    MIN(t.first_click) AS FirstClick,
    MAX(t.last_click) AS LastClick
FROM {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Newsletter_Contact_Topic t
INNER JOIN {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Contact c ON c.id = t.contact_id
GROUP BY t.contact_id, c.email, t.topic
'
SET
  @TechnicalDescription_41a0b455 = N'Newsletter_Contact_Topic grouped by contact_id and topic, joined to Contact for the email. Clicks = SUM(num_clicks), Weight = MAX(weight), first/last click widened across newsletters: the same merge rasa.io uses for one contact''s topics. Rank a person''s interests by Clicks or Weight.'
SET
  @Status_41a0b455 = N'Approved'
SET
